function rc17Settings(){const s=typeof rc16Settings==='function'?rc16Settings():store.settings||(store.settings={});s.brandProfiles=s.brandProfiles||{};s.brandProfiles.GLOBAL={...RC17_DEFAULT_BRAND,...(s.brandProfiles.GLOBAL||{})};s.communityViewModes=s.communityViewModes||{admin:'orbit',professional:'orbit'};s.communityTerritoryFilter=s.communityTerritoryFilter||{};s.broadcasts=Array.isArray(s.broadcasts)?s.broadcasts:[];s.idCounters=s.idCounters||{};s.supportTickets=s.supportTickets||{};s.navModeByRole=s.navModeByRole||{};return s}
function rc17RegionCode(id){return({CARIBBEAN:'CAR',USA:'USA',EUROPE:'EUR',ASIA:'ASI',OCEANIA:'OCE',LATAM:'LAT',CANADA:'CAN'}[id]||String(id||'REG').slice(0,3).toUpperCase())}
function rc17TerritoryCode(id){const map={'car-saint-martin':'SXM','car-guadeloupe':'GLP','car-martinique':'MTQ','car-saint-barthelemy':'SBH','car-bahamas':'BHS','car-jamaica':'JAM','car-barbados':'BRB','car-saint-kitts-nevis':'KNA','car-anguilla':'AIA','car-puerto-rico':'PRI','car-trinidad-tobago':'TTO','usa-indiana-hq':'IND'};if(map[id])return map[id];const p=String(id||'').split('-').filter(Boolean);return (p.slice(-2).map(x=>x[0]).join('')||p.pop()||'LOC').slice(0,3).toUpperCase()}
function rc17NextPublicId(regionId,territoryId,kind){const s=rc17Settings(),prefix=`${rc17RegionCode(regionId)}-${rc17TerritoryCode(territoryId)}-${kind}`,n=(s.idCounters[prefix]=Number(s.idCounters[prefix]||0)+1);return `${prefix}-${String(n).padStart(kind==='A'?4:6,'0')}`}
