function rc17BrandScopeForCurrent(){const c=currentClient();if(c)return `TERRITORY:${c.territoryId||''}`;const p=rc11AdminProfile?.();if(!p)return'GLOBAL';if(rc12IsWorldHq?.(p))return p.territoryId?`TERRITORY:${p.territoryId}`:'GLOBAL';if(rc12IsCaribbeanHq?.(p))return`REGION:CARIBBEAN`;return`TERRITORY:${p.territoryId||''}`}
function rc17BrandChain(scope){const out=[];if(scope?.startsWith('TERRITORY:')){const id=scope.split(':')[1],t=rc11Territory?.(id);out.push(scope);if(t?.regionId)out.push(`REGION:${t.regionId}`)}else if(scope?.startsWith('REGION:'))out.push(scope);out.push('GLOBAL');return out}
function rc17ResolveBrand(scope=rc17BrandScopeForCurrent()){const s=rc17Settings();for(const key of rc17BrandChain(scope)){if(s.brandProfiles[key])return{...RC17_DEFAULT_BRAND,...s.brandProfiles.GLOBAL,...s.brandProfiles[key],scope:key}}return{...RC17_DEFAULT_BRAND,scope:'GLOBAL'}}
function rc17AllowedBrandScopes(){const p=rc11AdminProfile?.();if(!p)return[];const arr=[];if(rc12IsWorldHq?.(p)){arr.push(['GLOBAL','Global platform']);for(const r of RC11_REGION_SEED||[])arr.push([`REGION:${r.id}`,`${r.flag||''} ${rc11RegionName(r.id)}`]);for(const t of rc11Territories?.()||[])arr.push([`TERRITORY:${t.id}`,`${rc15FlagForTerritory?.(t)||''} ${t.name}`])}else if(rc12IsCaribbeanHq?.(p)){arr.push(['REGION:CARIBBEAN','🌎 Caribbean region']);for(const t of rc11Territories?.('CARIBBEAN')||[])arr.push([`TERRITORY:${t.id}`,`${rc15FlagForTerritory?.(t)||''} ${t.name}`])}else{for(const id of rc12AllowedTerritories?.(p)||[p.territoryId]){const t=rc11Territory?.(id);if(t)arr.push([`TERRITORY:${id}`,`${rc15FlagForTerritory?.(t)||''} ${t.name}`])}}return arr}
