function rc17BindBrandStudio(){if(currentView!=='brand-studio')return;$('rc17BrandScope')?.addEventListener('change',e=>{rc17Settings().brandStudioScope=e.target.value;saveStore();renderShell()});document.querySelectorAll('[data-rc17-preset]').forEach(b=>b.onclick=()=>{const[a,c,d]=b.dataset.rc17Preset.split('|');$('rc17PrimaryColor').value=a;$('rc17SecondaryColor').value=c;$('rc17AccentColor').value=d;rc17LiveBrandPreview()});['rc17PrimaryColor','rc17SecondaryColor','rc17AccentColor'].forEach(id=>$(id)?.addEventListener('input',rc17LiveBrandPreview));$('rc17SaveBrand')?.addEventListener('click',async()=>{const s=rc17Settings(),scope=$('rc17BrandScope').value,old=s.brandProfiles[scope]||{},logo=$('rc17BrandLogo')?.files?.[0];let logoData=old.logoData||'';if(logo){if(logo.size>2.5*1024*1024)return toast('For this single-file prototype, keep the interface logo under 2.5 MB.');logoData=await rc17FileToDataUrl(logo)}s.brandProfiles[scope]={...old,primary:$('rc17PrimaryColor').value,secondary:$('rc17SecondaryColor').value,accent:$('rc17AccentColor').value,motionGuide:$('rc17MotionGuideToggle').checked,animations:$('rc17AnimationsToggle').checked,navMode:$('rc17NavMode').value,logoData,logoName:logo?.name||old.logoName||''};saveStore();rc17ApplyTheme();renderShell();toast('Brand profile saved and applied.')});$('rc17ResetBrand')?.addEventListener('click',()=>{const scope=$('rc17BrandScope').value;if(scope==='GLOBAL')rc17Settings().brandProfiles.GLOBAL={...RC17_DEFAULT_BRAND};else delete rc17Settings().brandProfiles[scope];saveStore();renderShell();toast('Brand scope reset.')})}
