function rc17HydrateNavigation(){const nav=document.querySelector('.sidebar nav');if(!nav)return;nav.classList.remove('rc17-command-rail');if(rc17NavMode()==='classic'){nav.querySelectorAll('.rc17-nav-group').forEach(g=>{const items=[...g.querySelectorAll(':scope .rc17-group-items>button[data-view]')];items.forEach(x=>nav.insertBefore(x,g));g.remove()});return}if(nav.classList.contains('rc17-command-rail')&&nav.querySelector('.rc17-nav-group'))return;const buttons=[...nav.querySelectorAll(':scope>button[data-view],:scope .rc17-nav-group .rc17-group-items>button[data-view]')];if(!buttons.length)return;buttons.forEach(b=>b.closest('.rc17-nav-group')?.remove());nav.innerHTML='';nav.classList.add('rc17-command-rail');const groups=(isAdmin()&&!currentClient())?RC17_ADMIN_GROUPS:RC17_PRO_GROUPS;const seen=new Set();for(const[gId,icon,label,views]of groups){const members=buttons.filter(b=>views.includes(b.dataset.view));if(!members.length)continue;members.forEach(b=>seen.add(b));const open=members.some(b=>b.classList.contains('active'));const group=document.createElement('section');group.className='rc17-nav-group'+(open?' open':'');group.dataset.group=gId;group.innerHTML=`<button class="rc17-group-head" type="button"><span class="rc17-gicon">${icon}</span><span>${label}</span><span class="rc17-chevron">⌄</span></button><div class="rc17-group-items"></div>`;const box=group.querySelector('.rc17-group-items');members.forEach(b=>box.appendChild(b));group.querySelector('.rc17-group-head').onclick=()=>group.classList.toggle('open');nav.appendChild(group)}const leftovers=buttons.filter(b=>!seen.has(b));if(leftovers.length){const g=document.createElement('section');g.className='rc17-nav-group';g.innerHTML='<button class="rc17-group-head" type="button"><span class="rc17-gicon">＋</span><span>More</span><span class="rc17-chevron">⌄</span></button><div class="rc17-group-items"></div>';leftovers.forEach(b=>g.querySelector('.rc17-group-items').appendChild(b));g.querySelector('.rc17-group-head').onclick=()=>g.classList.toggle('open');nav.appendChild(g)}}
