function rc17DashboardEnhancement(){if(currentView!=='dashboard'||!currentClient()||$('rc17DashPulse'))return;const t=tenantData(),orders=t.orders||[],now=new Date(),months=[];for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1),key=`${d.getFullYear()}-${d.getMonth()}`;months.push({key,label:d.toLocaleDateString('en-US',{month:'short'}),total:0})}for(const o of orders){const d=new Date(o.createdAt),m=months.find(x=>x.key===`${d.getFullYear()}-${d.getMonth()}`);if(m)m.total+=Number(o.totalEUR||0)}const max=Math.max(1,...months.map(x=>x.total)),out=orders.reduce((n,o)=>n+Number(rcOrderBalance?.(o)||0),0),total=orders.reduce((n,o)=>n+Number(o.totalEUR||0),0),pct=total?Math.min(100,Math.max(0,(total-out)/total*100)):0,html=`<div id="rc17DashPulse" class="rc17-dashboard-pulse"><section class="rc17-pulse-card"><span class="eyebrow">ACTIVITY PULSE</span><h3>6-month purchasing rhythm</h3><div class="rc17-mini-bars">${months.map(x=>`<div class="rc17-mini-bar"><i style="height:${Math.max(4,x.total/max*100)}%" title="${x.total.toFixed(2)} EUR"></i><small>${x.label}</small></div>`).join('')}</div></section><section class="rc17-pulse-card"><span class="eyebrow">PAYMENT STATUS</span><h3>Account progress</h3><div class="rc17-donut" style="--pct:${pct}%" data-label="${Math.round(pct)}%\ncollected"></div><p style="text-align:center;color:#6b8193;font-size:10px">Outstanding: ${rc11Money?.(out)||out.toFixed(2)}</p></section></div>`;const hero=document.querySelector('#content .rc11-page-hero,#content .hero');hero?.insertAdjacentHTML('afterend',html)}
