function rc17BindSupport(){if(currentView!=='support')return;document.querySelectorAll('[data-rc17-support]').forEach(b=>b.onclick=()=>{tenantData().supportMode=b.dataset.rc17Support;saveStore();renderShell()});$('rc17HumanSend')?.addEventListener('click',()=>{const q=$('rc17HumanMessage').value.trim();if(!q)return;const t=tenantData(),c=currentClient(),ticket=rc17Ticket(c.id);t.messages=t.messages||[];t.messages.push({id:rc11SafeId('msg'),authorRole:'client',authorId:c.id,text:q,createdAt:new Date().toISOString(),readByAdmin:false,ticketStatus:'open'});ticket.status='open';ticket.updatedAt=new Date().toISOString();ticket.history.push({at:new Date().toISOString(),action:'client_message'});saveStore();renderShell()});$('rc17SupportAISend')?.addEventListener('click',async()=>{const q=$('rc17SupportAIInput')?.value.trim(),body=$('rc17SupportAI');if(!q||!body)return;body.insertAdjacentHTML('beforeend',`<div class="rc12-ai-msg user">${rc17Esc(q)}</div>`);const a=rc12Settings().assistant;if(a.proxyUrl){try{const r=await fetch(a.proxyUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({agentId:a.agentId,text:q,language:a.language,sources:RC17_SOURCES,scope:{role:'professional',regionId:currentClient().regionId,territoryId:currentClient().territoryId}})});const d=await r.json();body.insertAdjacentHTML('beforeend',`<div class="rc12-ai-msg">${rc17Esc(d.text||'Response received.')}</div>`)}catch(e){body.insertAdjacentHTML('beforeend','<div class="rc12-ai-msg">Secure assistant connector unavailable.</div>')}}else body.insertAdjacentHTML('beforeend','<div class="rc12-ai-msg">Realtime connector not configured.</div>');$('rc17SupportAIInput').value='';body.scrollTop=body.scrollHeight})}
