function rc17RenderAdminSupport(){const a=rc12Settings().assistant;return rc11Hero('Administrator customer service','Two operational paths: ELIA for immediate AI guidance and Human Inbox for team-managed professional support.','SUPPORT OPERATIONS','',[`${rc17Esc(a.agentId||'xAI agent')}`])+`<div class="rc17-support-chooser"><button class="rc17-support-option active" id="rc17AdminAI"><span class="icon">✦</span><h3>ELIA Administrator AI</h3><p>Product, system, documentation, pricing and portal guidance.</p></button><button class="rc17-support-option" id="rc17AdminHuman"><span class="icon">◉</span><h3>Human Support Inbox</h3><p>Open professional tickets, handoffs, status and shared team history.</p></button></div><section class="rc17-support-panel"><div class="rc12-assistant-body" id="rc12AssistantBody"><div class="rc12-ai-msg">Ask ELIA. The production connector is instructed to use approved Elite Crete Systems sources.</div></div><div class="rc12-ai-compose"><input id="rc12AssistantInput" placeholder="Ask ELIA…" ${a.enabled?'':'disabled'}><button class="btn primary" id="rc12AssistantSend" ${a.enabled?'':'disabled'}>Send</button></div></section>`}
