rc17BindBroadcast=function(){if(currentView!=='broadcast-center')return;const sc=rc18BroadcastScope(),sync=()=>{const r=$('rc17BroadcastRegion').value,role=$('rc18BroadcastRole').value,ts=r==='__ALL__'?[]:rc11Territories(r).map(t=>t.id);$('rc17BroadcastTerritory').innerHTML=`<option value="__ALL__">All territories</option>`+ts.map(id=>`<option value="${id}">${rc18Esc(rc11Territory(id)?.name||id)}</option>`).join('');const t=$('rc17BroadcastTerritory').value,people=[];if(role!=='admins')for(const c of sc.clients)if((r==='__ALL__'||c.regionId===r)&&(t==='__ALL__'||c.territoryId===t))people.push({id:'pro:'+c.id,label:`Professional · ${c.company} — ${rc11RegionName(c.regionId)} · ${rc11Territory(c.territoryId)?.name||''}`});if(role!=='professionals')for(const a of sc.admins)if((r==='__ALL__'||a.regionId===r)&&(t==='__ALL__'||a.territoryId===t))people.push({id:'admin:'+a.id,label:`MD · ${a.name} — ${rc11RegionName(a.regionId)} · ${rc11Territory(a.territoryId)?.name||''}`});$('rc17BroadcastClients').innerHTML=people.map(x=>`<option value="${x.id}">${rc18Esc(x.label)}</option>`).join('')};$('rc17BroadcastRegion').onchange=sync;$('rc17BroadcastTerritory').onchange=sync;$('rc18BroadcastRole').onchange=sync;sync();$('rc17BroadcastSend').onclick=async()=>{const title=$('rc17BroadcastTitle').value.trim(),txt=$('rc17BroadcastText').value.trim();if(!title||!txt)return toast('Title and message are required.');const r=$('rc17BroadcastRegion').value,t=$('rc17BroadcastTerritory').value,role=$('rc18BroadcastRole').value,chosen=[...$('rc17BroadcastClients').selectedOptions].map(o=>o.value);let pros=sc.clients.filter(c=>(r==='__ALL__'||c.regionId===r)&&(t==='__ALL__'||c.territoryId===t)),admins=sc.admins.filter(a=>(r==='__ALL__'||a.regionId===r)&&(t==='__ALL__'||a.territoryId===t));if(role==='admins')pros=[];if(role==='professionals')admins=[];if(chosen.length){pros=pros.filter(c=>chosen.includes('pro:'+c.id));admins=admins.filter(a=>chosen.includes('admin:'+a.id))}if(!pros.length&&!admins.length)return toast('No recipient in the selected audience.');let imageData='';const f=$('rc17BroadcastImage').files?.[0];if(f){if(f.size>2.5*1024*1024)return toast('Keep the image under 2.5 MB in this prototype.');imageData=await rc17FileToDataUrl(f)}const links=$('rc17BroadcastLinks').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),priority=$('rc17BroadcastPriority').value,id=rc11SafeId('broadcast'),createdAt=new Date().toISOString();for(const c of pros){const tn=store.tenants[c.id]=store.tenants[c.id]||{};tn.notifications=tn.notifications||[];tn.notifications.unshift({id:id+'-'+c.id,title,text:txt,type:'broadcast',priority,imageData,links,createdAt,read:false})}const s=rc18S();s.adminNotifications=s.adminNotifications||{};for(const a of admins){const arr=s.adminNotifications[a.id]=s.adminNotifications[a.id]||[];arr.unshift({id:id+'-'+a.id,title,text:txt,type:'broadcast',priority,imageData,links,createdAt,read:false})}rc17Settings().broadcasts.unshift({id,title,text:txt,priority,links,createdAt,recipientCount:pros.length+admins.length,regionId:r,territoryId:t,role});saveStore();renderShell();toast(`Broadcast published to ${pros.length+admins.length} recipient(s).`)} };

